      "path": "packages/messaging-core/lib/session-map.js",
      "content": "/**\n * Chat-to-session mapping for the messaging gateway.\n *\n * A chat (platform + chat id) maps to a DSH session id of the shape\n * `msg-<platform>-<hash>` (deterministic from the chat key) with `-vN`\n * appended each time the user runs `/new` (fresh conversation). The mapping\n * plus chat metadata is persisted as JSONL under $DSH_HOME/messaging/ so the\n * outbound router can reverse session id -> chat and the status tool can list\n * chats.\n */\nimport { createHash } from 'node:crypto'\nimport { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\n\nfunction dshHome() {\n  return process.env.DSH_HOME || join(homedir(), '.dsh')\n}\n\nexport function createSessionMap({ logger }) {\n  const file = join(dshHome(), 'messaging', 'session-map.jsonl')\n  /** chatKey -> entry */\n  const byChat = new Map()\n  /** sessionId -> chatKey */\n  const bySession = new Map()\n  let loaded = false\n\n  function load() {\n    if (loaded) return\n    loaded = true\n    try {\n      if (!existsSync(file)) return\n      for (const line of readFileSync(file, 'utf8').split(/\\r?\\n/)) {\n        if (!line.trim()) continue\n        try {\n          const entry = JSON.parse(line)\n          if (entry && entry.chatKey && entry.sessionId) {\n            // Backfill history for entries written before /resume existed.\n            if (!Array.isArray(entry.history) || entry.history.length === 0) {\n              entry.history = [{ sessionId: entry.sessionId, generation: entry.generation || 0, updatedAt: entry.updatedAt || 0 }]\n            }\n            byChat.set(entry.chatKey, entry)\n            bySession.set(entry.sessionId, entry.chatKey)\n          }\n        } catch { /* skip malformed line */ }\n      }\n    } catch (error) {\n      logger.warn(`session map load failed (${file}): ${error.message}`)\n    }\n  }\n\n  function persist() {\n    try {\n      const dir = join(file, '..')\n      mkdirSync(dir, { recursive: true })\n      const lines = [...byChat.values()].map((entry) => JSON.stringify(entry))\n      writeFileSync(file, lines.length ? lines.join('\\n') + '\\n' : '')\n    } catch (error) {\n      logger.warn(`session map save failed (${file}): ${error.message}`)\n    }\n  }\n\n  function hashChatKey(chatKey) {\n    return createHash('sha1').update(chatKey).digest('hex').slice(0, 12)\n  }\n\n  function defaultId(chatKey, generation) {\n    const base = `msg-${chatKey.split(':')[0]}-${hashChatKey(chatKey)}`\n    return generation ? `${base}-v${generation}` : base\n  }\n\n  /** Deterministic session id for a chat (no entry required). */\n  function sessionIdFor(chatKey) {\n    load()\n    const entry = byChat.get(chatKey)\n    return entry ? entry.sessionId : defaultId(chatKey, 0)\n  }\n\n  /** Record/refresh chat metadata and return the entry. */\n  function touch(chatKey, meta) {\n    load()\n    const prev = byChat.get(chatKey)\n    const entry = {\n      chatKey,\n      sessionId: prev ? prev.sessionId : defaultId(chatKey, prev ? prev.generation : 0),\n      generation: prev ? prev.generation : 0,\n      history: prev && Array.isArray(prev.history) && prev.history.length ? prev.history : [],\n      ...meta,\n      updatedAt: Date.now(),\n    }\n    if (entry.history.length === 0) {\n      entry.history.push({ sessionId: entry.sessionId, generation: entry.generation, updatedAt: entry.updatedAt })\n    }\n    byChat.set(chatKey, entry)\n    bySession.set(entry.sessionId, chatKey)\n    persist()\n    return entry\n  }\n\n  /** Start a fresh conversation: bump generation past every historical one. */\n  function reset(chatKey) {\n    load()\n    const prev = byChat.get(chatKey)\n    if (prev) bySession.delete(prev.sessionId)\n    const history = prev && Array.isArray(prev.history) && prev.history.length ? prev.history : []\n    const generation = history.reduce((max, h) => Math.max(max, Number(h.generation) || 0), 0) + 1\n    const entry = {\n      ...(prev ? { platform: prev.platform, chatId: prev.chatId, threadId: prev.threadId, userId: prev.userId, userName: prev.userName } : {}),\n      chatKey,\n      sessionId: defaultId(chatKey, generation),\n      generation,\n      history,\n      updatedAt: Date.now(),\n    }\n    entry.history.push({ sessionId: entry.sessionId, generation, updatedAt: entry.updatedAt })\n    if (entry.history.length > 20) entry.history = entry.history.slice(-20)\n    byChat.set(chatKey, entry)\n    bySession.set(entry.sessionId, chatKey)\n    persist()\n    return entry\n  }\n\n  /** Per-chat session history (oldest first). */\n  function historyFor(chatKey) {\n    load()\n    const entry = byChat.get(chatKey)\n    return entry && Array.isArray(entry.history) ? entry.history : []\n  }\n\n  /** Switch the chat's active session to a past one (validated against history). */\n  function resume(chatKey, sessionId) {\n    load()\n    const entry = byChat.get(chatKey)\n    const history = entry && Array.isArray(entry.history) ? entry.history : []\n    if (!history.some((h) => h.sessionId === sessionId)) return false\n    if (entry && entry.sessionId === sessionId) return true\n    if (entry) bySession.delete(entry.sessionId)\n    const next = {\n      ...(entry || { chatKey }),\n      sessionId,\n      history,\n      updatedAt: Date.now(),\n    }\n    byChat.set(chatKey, next)\n    bySession.set(sessionId, chatKey)\n    persist()\n    return true\n  }\n\n  /** Cache a title on one history item (best-effort; /resume lists titles). */\n  function setHistoryTitle(chatKey, sessionId, title) {\n    load()\n    const entry = byChat.get(chatKey)\n    if (!entry || !Array.isArray(entry.history)) return\n    let changed = false\n    for (const h of entry.history) {\n      if (h.sessionId === sessionId && h.title !== title) {\n        h.title = title\n        changed = true\n      }\n    }\n    if (changed) persist()\n  }\n\n  function chatKeyFor(sessionId) {\n    load()\n    return bySession.get(sessionId)\n  }\n\n  function entryFor(chatKey) {\n    load()\n    return byChat.get(chatKey)\n  }\n\n  function entries() {\n    load()\n    return [...byChat.values()]\n  }\n\n  return { sessionIdFor, touch, reset, resume, setHistoryTitle, historyFor, chatKeyFor, entryFor, entries }\n}\n"
    },
    {
      "path": "packages/messaging-core/lib/agents.js",
      "content": "/**\n * Agent lifecycle for messaging chats.\n *\n * Mirrors the web host's canonical creation path (dsh-host-apiproxy):\n *   - single-flight creation per session id (concurrent same-id creation is\n *     unsupported by the registry),\n *   - resume when the session is already persisted, create otherwise,\n *   - setup composes the agent's scoped world: install the model selection\n *     (agentDefaultModel) and mount the default agent preset when a roster\n *     exists,\n *   - agentOptions provider/model come from ctx.agentDefaultModel.currentSelection().\n */\nimport { installModelSelection } from '@deepseek-ai/dsh-agent'\nimport { attachSessionToPlatformWorkspace, ensureWorkspaceDir } from './workspaces.js'\n\nexport function createAgentManager(ctx, { logger }) {\n  /** sessionId -> AgentHandle */\n  const handles = new Map()\n  /** sessionId -> in-flight creation promise */\n  const creations = new Map()\n\n  /** Install the live model selection on an unpublished agent scope. */\n  function installSelection(agentCtx) {\n    const agent = agentCtx.agent\n    if (!agent) throw new Error('messaging: agent setup has no scoped agent')\n    const defaults = ctx.get('agentDefaultModel')\n    if (!defaults || typeof defaults.currentSelection !== 'function') return\n    const selection = {\n      get current() {\n        return defaults.currentSelection()\n      },\n      set current(next) { /* per-session override unsupported in M0 */ },\n      assembled: undefined,\n    }\n    installModelSelection(agent.ctx, selection)\n  }\n\n  /** Resolve the default preset and build the pre-publication setup. */\n  async function composeSetup() {\n    const presets = ctx.get('agentPresets')\n    if (!presets) {\n      return { agentPreset: undefined, setup: async (agentCtx) => { installSelection(agentCtx) } }\n    }\n    const resolved = await presets.resolve(undefined)\n    return {\n      agentPreset: resolved.id,\n      setup: async (agentCtx) => {\n        installSelection(agentCtx)\n        await presets.mount(agentCtx, resolved.id)\n      },\n    }\n  }\n\n  function modelOptions() {\n    const defaults = ctx.get('agentDefaultModel')\n    const selection = defaults && typeof defaults.currentSelection === 'function' ? defaults.currentSelection() : undefined\n    if (!selection) return {}\n    return { provider: selection.provider, model: selection.model }\n  }\n\n  /** Resolve the live agent for a session id, creating/resuming it once. */\n  async function ensureAgent(sessionId, opts = {}) {\n    const live = ctx.agents.get(sessionId)\n    if (live) return live\n    let creation = creations.get(sessionId)\n    if (!creation) {\n      creation = (async () => {\n        const persistence = ctx.get('sessionPersistence')\n        let stored = false\n        if (persistence) {\n          try {\n            stored = (await persistence.list()).some((header) => header.id === sessionId)\n          } catch (error) {\n            logger.warn(`sessionPersistence.list failed: ${error.message}`)\n          }\n        }\n        const composition = await composeSetup()\n        const agentOptions = modelOptions()\n        const cwd = opts && opts.cwd ? opts.cwd : process.cwd()\n        const handle = stored\n          ? await ctx.agents.resume({ resumeSessionId: sessionId, agentOptions, setup: composition.setup })\n          : await ctx.agents.create({\n              sessionId,\n              agentOptions,\n              meta: {\n                cwd,\n                ...(composition.agentPreset ? { agentPreset: composition.agentPreset } : {}),\n              },\n              setup: composition.setup,\n            })\n        handles.set(sessionId, handle)\n        // Attribute the session to its platform workspace (best-effort, with\n        // retries so the session header is persisted before the attach).\n        if (opts && opts.platform) {\n          const attach = (attempt) => {\n            attachSessionToPlatformWorkspace(ctx, opts.platform, sessionId, opts.label).catch(() => {\n              if (attempt < 3) setTimeout(() => attach(attempt + 1), 1500)\n            })\n          }\n          attach(0)\n        }\n        return handle.agent\n      })().catch((error) => {\n        const concurrent = ctx.agents.get(sessionId)\n        if (concurrent) return concurrent\n        throw error\n      }).finally(() => {\n        creations.delete(sessionId)\n      })\n      creations.set(sessionId, creation)\n    }\n    return creation\n  }\n\n  /** Resolve the per-platform workspace directory (created on demand). */\n  function workspaceFor(platform) {\n    return ensureWorkspaceDir(platform)\n  }\n\n  /** Tear down one owned agent (used by /new). */\n  async function disposeAgent(sessionId) {\n    const handle = handles.get(sessionId)\n    if (!handle) return\n    handles.delete(sessionId)\n    await handle.dispose()\n  }\n\n  /** Tear down every owned agent (plugin disposal). */\n  async function disposeAll() {\n    const owned = [...handles.values()]\n    handles.clear()\n    for (const handle of owned) {\n      try {\n        await handle.dispose()\n      } catch (error) {\n        logger.warn(`agent dispose failed: ${error.message}`)\n      }\n    }\n  }\n\n  return { ensureAgent, workspaceFor, disposeAgent, disposeAll }\n}\n"
    },
    {
      "path": "packages/messaging-core/lib/outbound.js",
      "content": "/**\n * Outbound router: subscribes to durable `session/event` facts and pushes\n * them to the platform adapter owning each messaging chat.\n *\n * Streaming model (per session):\n *   - turn/start resets the buffer and starts the typing indicator;\n *   - assistant/chunk text deltas accumulate into the buffer; streaming\n *     platforms get throttled edit-message updates while the buffer stays\n *     under the platform's message cap (no truncation is ever sent — when the\n *     cap is hit, streaming preview stops and the final delivery chunks);\n *   - assistant/message (one per step) flushes immediately; if the provider\n *     emitted no chunks for that step the assembled text is appended;\n *   - turn/end finalizes: chunked delivery of the full text, then a short\n *     status line for aborted/error/blocked endings.\n */\n\nimport { renderForCapability } from './markdown.js'\n\nconst EDIT_THROTTLE_MS = 350\nconst TYPING_INTERVAL_MS = 4500\n\nfunction messageText(message) {\n  return (message && Array.isArray(message.content) ? message.content : [])\n    .filter((block) => block && block.type === 'text' && typeof block.text === 'string')\n    .map((block) => block.text)\n    .join('')\n}\n\nfunction splitText(text, cap) {\n  if (text.length <= cap) return [text]\n  const parts = []\n  let rest = text\n  while (rest.length > cap) {\n    let cut = rest.lastIndexOf('\\n', cap)\n    if (cut < cap / 2) cut = cap\n    parts.push(rest.slice(0, cut))\n    rest = rest.slice(cut).replace(/^\\n/, '')\n  }\n  if (rest) parts.push(rest)\n  return parts\n}\n\nexport function createOutboundRouter(ctx, { adapters, sessionMap, logger }) {\n  /** sessionId -> { turn, buffer, chunkedSteps, messageId, typingTimer, editTimer, editStopped } */\n  const state = new Map()\n\n  function chatInfoFor(sessionId) {\n    const chatKey = sessionMap.chatKeyFor(sessionId)\n    if (!chatKey) return undefined\n    const platform = chatKey.split(':')[0]\n    const adapter = adapters.get(platform)\n    if (!adapter) return undefined\n    const entry = sessionMap.entryFor(chatKey)\n    return {\n      adapter,\n      target: { chatId: entry && entry.chatId ? entry.chatId : chatKey.split(':').slice(1).join(':'), threadId: entry && entry.threadId },\n    }\n  }\n\n  function stateFor(sessionId) {\n    let s = state.get(sessionId)\n    if (!s) {\n      s = { turn: 0, buffer: '', chunkedSteps: new Set(), messageId: null, typingTimer: null, editTimer: null, editStopped: false }\n      state.set(sessionId, s)\n    }\n    return s\n  }\n\n  function clearEditTimer(s) {\n    if (s.editTimer) {\n      clearTimeout(s.editTimer)\n      s.editTimer = null\n    }\n  }\n\n  function stopTyping(sessionId, s) {\n    if (s.typingTimer) {\n      clearInterval(s.typingTimer)\n      s.typingTimer = null\n    }\n    void sessionId\n  }\n\n  function startTyping(sessionId, info) {\n    const s = stateFor(sessionId)\n    if (s.typingTimer || !info.adapter.capabilities.typing) return\n    info.adapter.sendTyping(info.target).catch(() => {})\n    s.typingTimer = setInterval(() => {\n      info.adapter.sendTyping(info.target).catch(() => {})\n    }, TYPING_INTERVAL_MS)\n  }\n\n  /** Throttled streaming edit (never truncates; stops preview above the cap). */\n  function scheduleEdit(sessionId, info, s) {\n    if (!info.adapter.capabilities.streaming || s.editTimer || s.editStopped) return\n    s.editTimer = setTimeout(() => {\n      s.editTimer = null\n      performEdit(sessionId, info, s).catch((error) => logger.warn(`streaming edit failed: ${error.message}`))\n    }, EDIT_THROTTLE_MS)\n  }\n\n  async function performEdit(sessionId, info, s) {\n    const cap = info.adapter.capabilities.maxMessageLength || 4000\n    const raw = s.buffer.trim()\n    if (!raw) return\n    if (raw.length > cap) {\n      // Never send truncated markup: stop the streaming preview, the final\n      // delivery will chunk the full text.\n      s.editStopped = true\n      return\n    }\n    const text = renderForCapability(raw, info.adapter.capabilities)\n    if (s.messageId === null) {\n      const result = await info.adapter.send(info.target, text)\n      s.messageId = result && result.messageId ? result.messageId : null\n    } else {\n      await info.adapter.editMessage(info.target, s.messageId, text)\n    }\n    void sessionId\n  }\n\n  async function sendChunked(info, raw) {\n    const cap = info.adapter.capabilities.maxMessageLength || 4000\n    const text = renderForCapability(raw, info.adapter.capabilities)\n    const parts = splitText(text, cap)\n    for (const part of parts) {\n      await info.adapter.send(info.target, part)\n    }\n  }\n\n  async function finalize(sessionId, info, s, reason) {\n    stopTyping(sessionId, s)\n    clearEditTimer(s)\n    const raw = s.buffer.trim()\n    if (raw) {\n      const cap = info.adapter.capabilities.maxMessageLength || 4000\n      const text = renderForCapability(raw, info.adapter.capabilities)\n      const parts = splitText(text, cap)\n      if (info.adapter.capabilities.streaming && s.messageId !== null) {\n        // Replace the streamed preview with the exact first chunk, then send\n        // any remainder as new messages.\n        await info.adapter.editMessage(info.target, s.messageId, parts[0])\n        for (const part of parts.slice(1)) {\n          await info.adapter.send(info.target, part)\n        }\n      } else {\n        for (const part of parts) {\n          await info.adapter.send(info.target, part)\n        }\n      }\n    }\n    if (reason) {\n      if (reason.kind === 'aborted') {\n        await info.adapter.send(info.target, '⏹ 已中断')\n      } else if (reason.kind === 'error') {\n        const detail = reason.error && (reason.error.message || reason.error.code)\n        await info.adapter.send(info.target, `⚠️ 本轮出错：${detail || '未知错误'}`)\n      } else if (reason.kind === 'blocked') {\n        await info.adapter.send(info.target, '⏸ 本轮被拒绝，未执行')\n      }\n    }\n  }\n\n  async function onSessionEvent(session, event) {\n    const info = chatInfoFor(session.id)\n    if (!info) return\n    const s = stateFor(session.id)\n    try {\n      switch (event.type) {\n        case 'turn/start': {\n          s.turn = event.data.turn\n          s.buffer = ''\n          s.chunkedSteps = new Set()\n          s.messageId = null\n          s.editStopped = false\n          clearEditTimer(s)\n          startTyping(session.id, info)\n          break\n        }\n        case 'assistant/chunk': {\n          const chunk = event.data.chunk\n          if (chunk && chunk.type === 'text-delta' && typeof chunk.text === 'string') {\n            s.buffer += chunk.text\n            s.chunkedSteps.add(event.data.step)\n            scheduleEdit(session.id, info, s)\n          }\n          break\n        }\n        case 'assistant/message': {\n          if (!s.chunkedSteps.has(event.data.step)) {\n            s.buffer += messageText(event.data.message)\n          }\n          clearEditTimer(s)\n          if (info.adapter.capabilities.streaming && s.messageId === null && !s.editStopped) {\n            await performEdit(session.id, info, s)\n          }\n          break\n        }\n        case 'turn/end': {\n          await finalize(session.id, info, s, event.data.reason)\n          break\n        }\n        default:\n          break\n      }\n    } catch (error) {\n      logger.error(`outbound routing failed for ${session.id}: ${error.stack || error.message}`)\n    }\n  }\n\n  function dispose() {\n    for (const s of state.values()) {\n      clearEditTimer(s)\n      stopTyping('', s)\n    }\n    state.clear()\n  }\n\n  return { onSessionEvent, dispose }\n}\n"
    },
    {
      "path": "packages/messaging-core/lib/workspaces.js",
      "content": "/**\n * Per-platform workspaces for messaging sessions.\n *\n * Each platform gets its own workspace directory under\n * `$DSH_HOME/messaging/workspace/<platform>`, registered with the host\n * workspace registry (dsh-workspace) so the sidebar groups sessions by\n * platform instead of leaving them Ungrouped. Agent sessions are created\n * with `meta.cwd` pointing at the platform directory, which the registry\n * indexes as the workspace path.\n */\nimport { mkdirSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\n\nfunction dshHome() {\n  return process.env.DSH_HOME || join(homedir(), '.dsh')\n}\n\nexport function workspaceRoot() {\n  return join(dshHome(), 'messaging', 'workspace')\n}\n\nexport function workspaceDirFor(platform) {\n  return join(workspaceRoot(), String(platform))\n}\n\n/** Create the platform workspace directory (idempotent) and return its path. */\nexport function ensureWorkspaceDir(platform) {\n  const dir = workspaceDirFor(platform)\n  mkdirSync(dir, { recursive: true })\n  return dir\n}\n\n/**\n * Resolve the host workspace registry. Plain property access only sees\n * ancestor-scope services; `dsh-workspace` mounts as a sibling entry, so\n * fall back to `ctx.get('workspaceRegistry')` (the reflect store).\n */\nexport function resolveWorkspaceRegistry(ctx) {\n  try {\n    if (ctx && ctx.workspaceRegistry) return ctx.workspaceRegistry\n  } catch { /* fall through */ }\n  try {\n    const found = ctx && typeof ctx.get === 'function' ? ctx.get('workspaceRegistry') : null\n    if (found) return found\n  } catch { /* fall through */ }\n  return null\n}\n\n/** Register (or resolve) the per-platform workspace record; entity or null. */\nexport async function ensurePlatformWorkspace(ctx, platform, title) {\n  const registry = resolveWorkspaceRegistry(ctx)\n  if (!registry) return null\n  const dir = workspaceDirFor(platform)\n  try {\n    let entity = null\n    try {\n      const created = await registry.create(dir, title)\n      entity = created || null\n    } catch { /* record may already exist; resolve below is authoritative */ }\n    if (!entity) {\n      try {\n        entity = await registry.resolveByPath(dir)\n      } catch { /* ignore */ }\n    }\n    return entity\n  } catch {\n    return null\n  }\n}\n\n/** Best-effort attach of a session id to its platform workspace. */\nexport async function attachSessionToPlatformWorkspace(ctx, platform, sessionId, title) {\n  const registry = resolveWorkspaceRegistry(ctx)\n  if (!registry) return\n  const ws = await ensurePlatformWorkspace(ctx, platform, title)\n  if (ws && typeof ws.attachSession === 'function') {\n    await ws.attachSession(sessionId)\n  } else {\n    const wsId = ws && (ws.id || ws.workspaceId)\n    if (wsId && registry.get) {\n      const entity = registry.get(wsId)\n      if (entity && typeof entity.attachSession === 'function') await entity.attachSession(sessionId)\n    }\n  }\n}\n"
    },
    {
      "path": "packages/messaging-core/lib/http.js",
      "content": "/**\n * Shared webhook HTTP listener for messaging platform adapters.\n *\n * One small node:http server on a dedicated port (default 127.0.0.1:8765)\n * hosts per-platform routes (LINE, Twilio, WhatsApp Cloud, ...). Adapters\n * register their path and handler; the server starts lazily on the first\n * registration. Raw request bodies are captured so adapters can verify\n * platform signatures (HMAC etc.). Public exposure is the user's reverse\n * proxy / tunnel, documented per platform.\n */\nimport { createServer } from 'node:http'\n\nconst MAX_BODY_BYTES = 10 * 1024 * 1024\n\nexport function createWebhookServer(ctx, { logger, port = 8765, host = '127.0.0.1' }) {\n  /** path -> async ({ req, res, url, raw, method, headers }) => void */\n  const routes = new Map()\n  let server = null\n\n  function register(path, handler) {\n    if (routes.has(path)) throw new Error(`webhook path already registered: ${path}`)\n    routes.set(path, handler)\n    ensureStarted()\n    return () => {\n      routes.delete(path)\n    }\n  }\n\n  function ensureStarted() {\n    if (server) return\n    server = createServer((req, res) => {\n      handle(req, res).catch((error) => {\n        logger.error(`webhook ${req.url} failed: ${error.stack || error.message}`)\n        if (!res.headersSent) {\n          res.writeHead(500)\n          res.end('internal error')\n        }\n      })\n    })\n    server.listen(port, host, () => {\n      logger.info(`webhook listener on http://${host}:${port}`)\n    })\n    server.on('error', (error) => {\n      logger.error(`webhook listener error: ${error.message}`)\n    })\n  }\n\n  async function handle(req, res) {\n    const url = new URL(req.url || '/', 'http://localhost')\n    const handler = routes.get(url.pathname)\n    if (!handler) {\n      res.writeHead(404)\n      res.end()\n      return\n    }\n    const chunks = []\n    let size = 0\n    for await (const chunk of req) {\n      size += chunk.length\n      if (size > MAX_BODY_BYTES) {\n        res.writeHead(413)\n        res.end()\n        return\n      }\n      chunks.push(chunk)\n    }\n    const raw = Buffer.concat(chunks)\n    await handler({ req, res, url, raw, method: req.method || 'GET', headers: req.headers })\n  }\n\n  function stop() {\n    if (server) {\n      try {\n        if (typeof server.closeAllConnections === 'function') server.closeAllConnections()\n        server.close()\n      } catch { /* ignore */ }\n      server = null\n    }\n  }\n\n  return { register, stop }\n}\n"
    },
    {
      "path": "packages/messaging-core/lib/platforms/telegram.js",
      "content": "/**\n * platform-telegram — Telegram messaging adapter for DSH.\n *\n * grammY long polling; supports streaming edits (HTML), typing indicators,\n * text/photo/document sends, DM + group mention gating, and the shared\n * allowlist authorization provided by messaging-core.\n *\n * Configuration (settings namespace `messaging-telegram`, or env fallback):\n *   token:        Telegram bot token from @BotFather (env: TELEGRAM_BOT_TOKEN)\n *   allowedUsers: array of numeric user ids allowed to talk to the bot\n *   allowAll:     true to accept everyone (dev only)\n *   homeChannel:  default chat id for cron/notification delivery (reserved)\n */\nimport z from 'schemastery'\nimport { Bot } from 'grammy'\nimport { settingsNamespace } from '@deepseek-ai/dsh-settings'\n\n\nfunction escapeRegExp(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n}\n\nexport function register(ctx) {\n  const logger = ctx.logger('telegram')\n\n  let cfgScope\n  try {\n    cfgScope = ctx.settings.register(settingsNamespace('messaging-telegram'), z.object({\n      token: z.string().role('secret').default(''),\n      allowedUsers: z.array(z.union([z.number(), z.string()])).default([]),\n      allowAll: z.boolean().default(false),\n      homeChannel: z.string().default(''),\n    }))\n  } catch (error) {\n    logger.warn(`settings namespace 'messaging-telegram' unavailable: ${error.message}`)\n  }\n\n  function resolveConfig() {\n    const resolved = cfgScope ? cfgScope.get() : { token: '', allowedUsers: [], allowAll: false, homeChannel: '' }\n    const token = (resolved.token && resolved.token.trim()) || process.env.TELEGRAM_BOT_TOKEN || ''\n    return { ...resolved, token }\n  }\n\n  let bot = null\n  let me = null\n  let running = null // bot.start() promise\n\n  const adapter = {\n    id: 'telegram',\n    connected: false,\n    capabilities: {\n      streaming: true,\n      typing: true,\n      buttons: false,\n      media: ['photo', 'audio', 'document', 'video'],\n      markdown: 'html',\n      maxMessageLength: 4000,\n    },\n    resolveConfig,\n\n    async connect() {\n      if (bot) return\n      const cfg = resolveConfig()\n      if (!cfg.token) {\n        logger.warn('telegram: token 未配置（settings messaging-telegram.token 或 TELEGRAM_BOT_TOKEN）')\n        return\n      }\n      const b = new Bot(cfg.token)\n      bot = b\n      try {\n        b.on('message', (msgCtx) => {\n          handleUpdate(msgCtx).catch((error) => logger.error(`telegram update failed: ${error.stack || error.message}`))\n        })\n        await b.init()\n        me = b.botInfo\n        await b.api.deleteWebhook().catch(() => { /* not configured as webhook */ })\n        running = b.start({\n          onStart: () => {\n            adapter.connected = true\n            logger.info(`telegram connected as @${me.username} (${me.id})`)\n          },\n        }).catch((error) => {\n          logger.error(`telegram polling stopped: ${error.message}`)\n        })\n      } catch (error) {\n        // A failed connect must not leave the instance behind, or a later\n        // settings change can never trigger a reconnect.\n        bot = null\n        me = null\n        throw error\n      }\n    },\n\n    async disconnect() {\n      const b = bot\n      bot = null\n      me = null\n      adapter.connected = false\n      if (b) {\n        try {\n          await b.stop()\n        } catch { /* ignore */ }\n      }\n    },\n\n    async send(target, text) {\n      const chatId = Number(target.chatId)\n      const extra = target.threadId ? { message_thread_id: Number(target.threadId) } : {}\n      try {\n        const result = await bot.api.sendMessage(chatId, text, { parse_mode: 'HTML', ...extra })\n        return { messageId: String(result.message_id) }\n      } catch (error) {\n        if (isParseError(error)) {\n          const result = await bot.api.sendMessage(chatId, text, { ...extra })\n          return { messageId: String(result.message_id) }\n        }\n        throw error\n      }\n    },\n\n    async editMessage(target, messageId, text) {\n      const chatId = Number(target.chatId)\n      const extra = target.threadId ? { message_thread_id: Number(target.threadId) } : {}\n      try {\n        await bot.api.editMessageText(chatId, Number(messageId), text, { parse_mode: 'HTML', ...extra })\n      } catch (error) {\n        if (isNotModified(error)) return\n        if (isParseError(error)) {\n          await bot.api.editMessageText(chatId, Number(messageId), text, { ...extra })\n          return\n        }\n        throw error\n      }\n    },\n\n    async sendTyping(target) {\n      await bot.api.sendChatAction(Number(target.chatId), 'typing')\n    },\n\n    async sendMedia(target, media, caption) {\n      const chatId = Number(target.chatId)\n      const extra = target.threadId ? { message_thread_id: Number(target.threadId) } : {}\n      const cap = caption ? { caption, parse_mode: 'HTML', ...extra } : extra\n      let result\n      if (media.type === 'photo') result = await bot.api.sendPhoto(chatId, media.url, cap)\n      else if (media.type === 'document') result = await bot.api.sendDocument(chatId, media.url, cap)\n      else if (media.type === 'video') result = await bot.api.sendVideo(chatId, media.url, cap)\n      else if (media.type === 'audio') result = await bot.api.sendAudio(chatId, media.url, cap)\n      else {\n        await bot.api.sendMessage(chatId, `[媒体] ${media.url || ''}`, { ...extra })\n        return {}\n      }\n      return { messageId: String(result.message_id) }\n    },\n\n    async getChatInfo(chatId) {\n      const chat = await bot.api.getChat(Number(chatId))\n      return { name: chat.title || chat.first_name || String(chatId), type: chat.type, chatId: String(chat.id) }\n    },\n  }\n\n  const unregister = ctx.messaging.registerAdapter(adapter)\n  ctx.on('dispose', () => {\n    unregister()\n    adapter.disconnect().catch(() => {})\n  })\n\n  // Connect now if configured; also react to later configuration changes.\n  const initial = resolveConfig()\n  if (initial.token) {\n    adapter.connect().catch((error) => logger.error(`telegram connect failed: ${error.stack || error.message}`))\n  } else {\n    logger.warn('telegram: 未配置 token，等待配置（settings messaging-telegram.token）')\n  }\n  if (cfgScope && typeof cfgScope.watch === 'function') {\n    cfgScope.watch((next) => {\n      if (next.token && !bot) {\n        adapter.connect().catch((error) => logger.error(`telegram connect failed: ${error.stack || error.message}`))\n      }\n    })\n  }\n\n  /** Normalize one Telegram message update into a messaging-core inbound event. */\n  async function handleUpdate(msgCtx) {\n    if (!me) return\n    const m = msgCtx.message\n    if (!m || !m.from || m.from.is_bot || m.from.id === me.id) return\n\n    const chat = m.chat\n    const isGroup = chat.type === 'group' || chat.type === 'supergroup'\n    let text = m.text || m.caption || ''\n    const hasMedia = Boolean(m.photo || m.voice || m.document || m.video || m.audio || m.sticker)\n\n    if (isGroup) {\n      const mention = `@${me.username}`\n      const entities = m.entities || m.caption_entities || []\n      const mentioned = entities.some((e) => e.type === 'mention' && text.slice(e.offset, e.offset + e.length) === mention)\n      const repliedToBot = m.reply_to_message && m.reply_to_message.from && m.reply_to_message.from.id === me.id\n      if (!mentioned && !repliedToBot) return\n      text = text.replace(new RegExp(escapeRegExp(mention), 'g'), '').trim()\n    }\n\n    if (hasMedia) {\n      text = text ? `${text}\\n[（附带一个附件，当前版本不解析媒体内容）]` : '[收到一个附件（图片/语音/文件），当前版本不解析媒体内容]'\n    }\n    if (!text) return\n\n    await ctx.messaging.handleInbound('telegram', {\n      platform: 'telegram',\n      chatKey: `telegram:${chat.id}`,\n      chatId: String(chat.id),\n      threadId: m.message_thread_id ? String(m.message_thread_id) : undefined,\n      userId: String(m.from.id),\n      userName: m.from.username || m.from.first_name || String(m.from.id),\n      text,\n      raw: m,\n    })\n  }\n}\n\nfunction isNotModified(error) {\n  return /not modified/i.test(String(error && error.message ? error.message : error))\n}\n\nfunction isParseError(error) {\n  return /can't parse entities|parse entities/i.test(String(error && error.message ? error.message : error))\n}\n"
